package com.kivkung.universalclipboard;
import android.app.Activity;import android.net.Uri;import android.os.Bundle;import android.widget.TextView;import java.io.*;import java.security.*;
public final class GenericReadActivity extends Activity {boolean checked;public void onCreate(Bundle b){super.onCreate(b);TextView t=new TextView(this);t.setText("External application reading generic history attachment");setContentView(t);}public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(!focus||checked)return;checked=true;String result;try{android.content.ClipData clip=getSystemService(android.content.ClipboardManager.class).getPrimaryClip();Uri uri=clip==null?null:clip.getItemAt(0).getUri();if(uri==null)throw new IOException("Clipboard URI missing");MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=getContentResolver().openInputStream(uri)){byte[] bytes=new byte[1024];int n;while((n=in.read(bytes))!=-1)d.update(bytes,0,n);}StringBuilder h=new StringBuilder();for(byte x:d.digest())h.append(String.format("%02x",x&255));try(android.database.Cursor cursor=getContentResolver().query(uri,null,null,null,null)){if(cursor==null||!cursor.moveToFirst()||!cursor.getString(cursor.getColumnIndex("_display_name")).equals("fixture.bin")||cursor.getLong(cursor.getColumnIndex("_size"))!=6||!"application/octet-stream".equals(getContentResolver().getType(uri)))throw new IOException("Bad external metadata");}result="OK "+h+" "+uri;}catch(Exception e){result="FAIL "+e;}getSharedPreferences("paste",MODE_PRIVATE).edit().putString("generic",result).commit();}}
